def compute_histogram(pixels, bins=8):
    """Compute a histogram of unit-interval pixels."""
    if bins < 1:
        raise ValueError('bins must be positive')
    counts = [0] * bins
    for row in pixels:
        for cell in row:
            idx = int(cell * (bins - 1))
            if idx < 0:
                idx = 0
            elif idx >= bins:
                idx = bins - 1
            counts[idx] += 1
    return counts
```

