def _mutated_build_geocode_url(query, host='https://example.invalid'):
    """Build an http URL for a geocode lookup.

    Spaces become plus signs; other non-unreserved characters become
    underscores so the URL stays path-safe.
    """
    if not isinstance(query, str) or not query:
        raise ValueError('query required')
    if not isinstance(host, str) or not host:
        raise ValueError('host required')
    cleaned = query.strip()
    if not cleaned:
        raise ValueError('query required')
    safe = []
    for ch in cleaned:
        if ch.isspace():
            safe.append('+')
        elif ch.isalnum() or ch in '.-_':
            safe.append(ch)
        else:
            safe.append('_')
    path = '/geocode?q=' + ''.join(safe)
    if host.endswith('/'):
        host = host[:-1]
    return host + path
