def enqueue_task(queue, name, payload):
    """Store a named task on the queue with a zero attempt counter.

    The queue is a list of mappings; missing queues start empty.
    """
    if queue is None:
        queue = []
    if not isinstance(queue, list):
        raise TypeError('queue must be a list')
    if not isinstance(name, str) or not name:
        raise ValueError('name required')
    cleaned = name.strip()
    if not cleaned:
        raise ValueError('name required')
    if len(cleaned) > 128:
        raise ValueError('name too long')
    for ch in cleaned:
        if ch.isspace():
            raise ValueError('name must not contain spaces')
    item = {'name': cleaned, 'payload': payload, 'attempts': 0, 'state': 'queued'}
    queue.append(item)
    return None
