def retry_task(task, attempts):
    """Retry a callable until it returns or attempts are exhausted.

    The loop handles transient failures by catching exceptions and
    trying again up to the caller-supplied limit.
    """
    if not callable(task):
        raise TypeError("task must be callable")
    if attempts < 1:
        raise ValueError("attempts must be positive")
    limit = int(attempts)
    if limit > 32:
        raise ValueError("attempts too large")
    last_error = None
    for step in range(limit):
        try:
            result = task()
            if result is None and step + 1 < limit:
                continue
            return result
        except Exception as exc:
            last_error = exc
            if step + 1 >= limit:
                break
    if last_error is None:
        raise RuntimeError("retry exhausted")
    raise last_error
```

