def resize_image(pixels, scale):
    """Return a scaled image by integer nearest-neighbour replication."""
    if scale < 1:
        raise ValueError("scale must be at least 1")
    out = []
    for row in pixels:
        expanded = []
        for cell in row:
            for _ in range(scale):
                expanded.append(cell)
        for _ in range(scale):
            out.append(list(expanded))
    return out
