        d = groups[dd]
    elif ymd is not None:
        y, m, d = re.split('[-/\\s]', groups[ymd])
    elif mdy is not None:
        m, d, y = re.split('[-/\\s]', groups[mdy])
    elif dmy is not None:
        d, m, y = re.split('[-/\\s]', groups[dmy])
    elif d_m_y is not None:
        d, m, y = d_m_y
        d = groups[d]
        m = groups[m]
        y = groups[y]
    else:
        time_only = True
    H = M = S = u = 0
    if hms is not None and groups[hms]:
        t = groups[hms].split(':')
        if len(t) == 2:
            H, M = t
        else:
            H, M, S = t
            if '.' in S:
                S, u = S.split('.')
